#include <memory>
#include <iostream>

// A C-style resource that needs a special cleanup function.
struct C_Resource { int id; };
C_Resource* acquire_c_resource(int id) { return new C_Resource{id}; }
void release_c_resource(C_Resource* res) { 
    std::cout << "Releasing C_Resource " << res->id << std::endl;
    delete res; 
}

// A stateless lambda deleter.
auto c_deleter = [](C_Resource* res) { 
    release_c_resource(res);
};

// The deleter's type is part of the unique_ptr's type.
std::unique_ptr<C_Resource, decltype(c_deleter)> ptr1(acquire_c_resource(101), c_deleter);

// Another deleter type.
void other_deleter_func(C_Resource* res) { delete res; }

// This creates a different, incompatible unique_ptr type.
std::unique_ptr<C_Resource, void(*)(C_Resource*)> ptr2(acquire_c_resource(202), other_deleter_func);

// ptr1 = std::move(ptr2); // COMPILE ERROR: Incompatible types due to different deleters.
